	const minWidth = 220;
	const maxWidth = Math.max(minWidth, Math.min(640, Math.floor(containerRect.width * .6)));
	const onMove = (moveEvent) => {
		onWidthChange(Math.min(maxWidth, Math.max(minWidth, moveEvent.clientX - containerRect.left)));
	};
	const onUp = () => {
		window.removeEventListener("mousemove", onMove);
		window.removeEventListener("mouseup", onUp);
	};
